selector_to_html = {"a[href=\"#data\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Data<a class=\"headerlink\" href=\"#data\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#functions\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Functions<a class=\"headerlink\" href=\"#functions\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#module-contents\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Module Contents<a class=\"headerlink\" href=\"#module-contents\" title=\"Link to this heading\">#</a></h2><h3>Functions<a class=\"headerlink\" href=\"#functions\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#module-tests.conftest\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\"><a class=\"reference internal\" href=\"#module-tests.conftest\" title=\"tests.conftest\"><code class=\"xref py py-mod docutils literal notranslate\"><span class=\"pre\">tests.conftest</span></code></a><a class=\"headerlink\" href=\"#module-tests.conftest\" title=\"Link to this heading\">#</a></h1><p>The top-level test configuration file.</p>", "a[href=\"#tests.conftest.options\"]": "<dt class=\"sig sig-object py\" id=\"tests.conftest.options\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">tests.conftest.</span></span><span class=\"sig-name descname\"><span class=\"pre\">options</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/library/typing.html#typing.List\" title=\"(in Python v3.14)\"><span class=\"pre\">List</span></a><span class=\"p\"><span class=\"pre\">[</span></span><a class=\"reference external\" href=\"https://docs.python.org/3/library/typing.html#typing.Dict\" title=\"(in Python v3.14)\"><span class=\"pre\">Dict</span></a><span class=\"p\"><span class=\"pre\">[</span></span><a class=\"reference external\" href=\"https://docs.python.org/3/library/stdtypes.html#str\" title=\"(in Python v3.14)\"><span class=\"pre\">str</span></a><span class=\"p\"><span class=\"pre\">,</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/library/typing.html#typing.Any\" title=\"(in Python v3.14)\"><span class=\"pre\">Any</span></a><span class=\"p\"><span class=\"pre\">]</span></span><span class=\"p\"><span class=\"pre\">]</span></span></span></dt><dd><p>None</p><p>Defines additional pytest configuration items.</p><p>List entries are <a class=\"reference external\" href=\"https://docs.pytest.org/en/latest/reference/reference.html#pytest.Parser.addini\" title=\"pytest 9.2.0.dev277\"><code class=\"docutils literal notranslate\"><span class=\"pre\">pytest.Parser.addini</span></code></a> kwargs.  A default value\nmatching the configuration item\u2019s type is <strong>REQUIRED</strong>.  For example:</p></dd>", "a[href=\"#tests.conftest.pytest_addoption\"]": "<dt class=\"sig sig-object py\" id=\"tests.conftest.pytest_addoption\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">tests.conftest.</span></span><span class=\"sig-name descname\"><span class=\"pre\">pytest_addoption</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">parser</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.pytest.org/en/latest/reference/reference.html#pytest.Parser\" title=\"(in pytest v9.2.0.dev277)\"><span class=\"pre\">pytest.Parser</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">pluginmanager</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.pytest.org/en/latest/reference/reference.html#pytest.PytestPluginManager\" title=\"(in pytest v9.2.0.dev277)\"><span class=\"pre\">pytest.PytestPluginManager</span></a></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Customize the pytest configuration file and CLI arguments.</p></dd>", "a[href=\"#api\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">API<a class=\"headerlink\" href=\"#api\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#tests.conftest.pytest_configure\"]": "<dt class=\"sig sig-object py\" id=\"tests.conftest.pytest_configure\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">tests.conftest.</span></span><span class=\"sig-name descname\"><span class=\"pre\">pytest_configure</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">config</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.pytest.org/en/latest/reference/reference.html#pytest.Config\" title=\"(in pytest v9.2.0.dev277)\"><span class=\"pre\">pytest.Config</span></a></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Load the custom pytest configuration into the test session.</p><p>Access the configuration via\n<a class=\"reference external\" href=\"https://docs.pytest.org/en/latest/reference/reference.html#std-fixture-pytestconfig\" title=\"pytest 9.2.0.dev277\"><code class=\"docutils literal notranslate\"><span class=\"pre\">pytestconfig</span></code></a>, e.g.,\n<code class=\"docutils literal notranslate\"><span class=\"pre\">pytestconfig.option.the_option_name</span></code>.</p><p>Allow overriding the configuration via the process environment.\nEnvironment variables must use option names converted to upper\ncase, e.g,. <code class=\"docutils literal notranslate\"><span class=\"pre\">THE_OPTION_NAME</span></code>.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
